import requests
from flask import Flask, request
from urllib.parse import urljoin

app = Flask(__name__)

ALLOWED_DOMAINS = {"example.com", "safe.example.com"}  # Define allowed domains for SSRF protection

@app.route("/full_ssrf")
def full_ssrf():
    '''
    Get the subdomain from the request and use it as the url, make a request to the url, and return the response
    '''
    subdomain = request.args.get('subdomain')
    if not subdomain or not any(subdomain.endswith(domain) for domain in ALLOWED_DOMAINS):
        return "Invalid subdomain", 400

    base_url = "http://" + subdomain
    try:
        response = requests.get(base_url, timeout=5)
        # Ensure the response is safe to return (no XSS vulnerabilities)
        if response.status_code == 200:
            return response.text, response.status_code, {'Content-Type': 'text/plain'}
        else:
            return f"Error: {response.status_code}", response.status_code
    except requests.RequestException as e:
        return f"Request failed: {str(e)}", 500

if __name__ == "__main__":
    app.run(debug=True)
